target.css:
:root {
  --ink: #29263b;
  --muted: #716b84;
  --paper: #fffdfa;
  --line: #ded8e9;
  --lilac: #eee9ff;
  --violet: #7157b7;
  --coral: #e58470;
  --mint: #78bca5;
  --lemon: #f5c95b;
}

.formula-card {
  box-sizing: border-box;
  width: 490px;
  padding: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.formula-card * {
  box-sizing: border-box;
}

.formula-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.atelier-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  color: var(--paper);
  background: var(--violet);
  border-radius: 12px 12px 4px 12px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.title-block {
  min-width: 0;
}

.title-block h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 750;
  letter-spacing: -0.3px;
  line-height: 1.15;
}

.title-block p {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.2;
}

.batch-state {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-left: auto;
  padding: 5px 8px;
  color: var(--violet);
  background: var(--lilac);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.batch-state::before {
  width: 6px;
  height: 6px;
  content: "";
  background: var(--mint);
  border-radius: 50%;
}

.batch-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 12px;
  padding: 8px 0;
  background: var(--lilac);
  border-radius: 10px;
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 0 11px;
  border-right: 1px solid var(--line);
}

.detail:last-child {
  border-right: 0;
}

.detail span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.detail strong {
  font-size: 12px;
  line-height: 1.15;
}

.accords {
  margin-top: 12px;
}

.accords-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.accords-heading h2 {
  margin: 0;
  font-size: 14px;
  letter-spacing: -0.1px;
}

.accords-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.formula-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.formula-list li {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr);
  gap: 7px;
  align-items: center;
  padding: 8px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 9px;
}

.note-swatch {
  width: 8px;
  height: 30px;
  border-radius: 999px;
}

.note-swatch.top {
  background: var(--lemon);
}

.note-swatch.heart {
  background: var(--coral);
}

.note-swatch.base {
  background: var(--mint);
}

.note-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 2px;
}

.note-copy strong {
  font-size: 11px;
  line-height: 1;
}

.note-copy small {
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.measure {
  grid-column: 2;
  color: var(--violet);
  font-size: 10px;
  font-weight: 750;
}

.formula-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

.tag {
  color: var(--violet);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.save-button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  color: var(--paper);
  background: var(--ink);
  border: 0;
  border-radius: 8px;
  font: inherit;
  font-size: 11px;
  font-weight: 700;
}

.save-button span {
  color: var(--lemon);
  font-size: 15px;
  line-height: 10px;
}

